  "A standing mist": ["立つ霧", "멈춘 안개", "静立之雾", "靜立之霧", "Làn sương đứng", "Kabut yang berdiri", "หมอกที่ยืนนิ่ง", "Duran bir sis", "Una niebla inmóvil", "Uma névoa parada", "Стоячий туман", "Стоячий туман"],
  "A split stone": ["割れた石", "갈라진 돌", "裂石", "裂石", "Hòn đá nứt", "Batu terbelah", "หินแตก", "Yarık bir taş", "Una piedra partida", "Uma pedra rachada", "Расколотый камень", "Розколотий камінь"],
  "Foxfire": ["狐火", "여우불", "狐火", "狐火", "Lửa cáo", "Api rubah", "ไฟจิ้งจอก", "Tilki ateşi", "Fuego fatuo", "Fogo-fátuo", "Лисий огонь", "Лисячий вогонь"],
  "You need a Mysteries level of {n} for that.": ["それには神秘レベル{n}が必要だ。", "그러려면 신비 레벨 {n}이 필요하다.", "这需要奥秘等级 {n}。", "這需要奧秘等級 {n}。", "Bạn cần cấp Huyền bí {n} cho điều đó.", "Kau butuh level Misteri {n} untuk itu.", "คุณต้องมีเลเวลความลึกลับ {n} สำหรับสิ่งนั้น", "Bunun için {n}. seviye Gizemler gerekiyor.", "Necesitas nivel {n} de Misterios para eso.", "Você precisa de nível {n} em Mistérios para isso.", "Для этого нужен уровень Тайн {n}.", "Для цього потрібен рівень Таємниць {n}."],
  "{x} isn't ready again yet ({n}s).": ["{x}はまだ使えない({n}秒)。", "{x}은(는) 아직 준비되지 않았다 ({n}초).", "{x}还没准备好({n} 秒)。", "{x}還沒準備好({n} 秒)。", "{x} chưa sẵn sàng lại ({n} giây).", "{x} belum siap lagi ({n} dtk).", "{x} ยังไม่พร้อมอีกครั้ง ({n} วิ)", "{x} henüz hazır değil ({n} sn).", "{x} aún no está listo ({n} s).", "{x} ainda não está pronto ({n} s).", "{x} ещё не готов ({n} с).", "{x} ще не готовий ({n} с)."],
  "You set your edge against what the {x} fears.": ["{x}が恐れるものに刃を合わせる。", "{x}이(가) 두려워하는 것에 날을 맞춘다.", "你把刃锋对准{x}害怕的东西。", "你把刃鋒對準{x}害怕的東西。", "Bạn đặt lưỡi vũ khí nhắm vào thứ {x} sợ.", "Kau mengarahkan matamu pada apa yang ditakuti {x}.", "คุณตั้งคมอาวุธต่อสิ่งที่{x}กลัว", "Ağzını {x} neden korkuyorsa ona karşı ayarlarsın.", "Ajustas tu filo a lo que teme {x}.", "Você ajusta seu gume ao que {x} teme.", "Ты настраиваешь клинок на то, чего боится {x}.", "Ти налаштовуєш лезо на те, чого боїться {x}."],
  "You see the pattern the {x} keeps, and break it.": ["{x}が保つ型を見抜き、崩す。", "{x}이(가) 지키는 패턴을 꿰뚫고, 깬다.", "你看穿了{x}的路数,并打破了它。", "你看穿了{x}的路數,並打破了它。", "Bạn thấy khuôn mẫu {x} giữ, và phá nó.", "Kau melihat pola yang dijaga {x}, dan memecahkannya.", "คุณเห็นแบบแผนที่{x}ยึดไว้ แล้วทำลายมัน", "{x} hangi örüntüyü tutuyor görür ve kırarsın.", "Ves el patrón que sigue {x}, y lo rompes.", "Você vê o padrão que {x} segue, e o quebra.", "Ты видишь узор, которого держится {x}, и разрываешь его.", "Ти бачиш візерунок, якого тримається {x}, і розриваєш його."],
  "The {x} doesn't come close enough to be weighed.": ["{x}は量れるほど近くに来ない。", "{x}은(는) 저울질할 만큼 가까이 오지 않는다.", "{x}不会近到能掂量的地步。", "{x}不會近到能掂量的地步。", "{x} không đến đủ gần để được cân nhắc.", "{x} tak datang cukup dekat untuk ditimbang.", "{x}ไม่เข้ามาใกล้พอให้ชั่งได้", "{x} tartılacak kadar yaklaşmıyor.", "{x} no se acerca lo bastante para ser sopesado.", "{x} não chega perto o bastante para ser pesado.", "{x} не подходит достаточно близко, чтобы его взвесить.", "{x} не підходить достатньо близько, щоб його зважити."],
  "The {x} isn't a wayward spirit: there's no thread to cut.": ["{x}は迷える霊ではない。断つ糸がない。", "{x}은(는) 떠도는 영혼이 아니다. 끊을 실이 없다.", "{x}不是游荡之灵:没有线可斩。", "{x}不是遊蕩之靈:沒有線可斬。", "{x} không phải linh hồn lạc lối: không có sợi chỉ nào để cắt.", "{x} bukan roh tersesat: tak ada benang untuk diputus.", "{x}ไม่ใช่วิญญาณพเนจร ไม่มีสายให้ตัด", "{x} başıboş bir ruh değil: kesilecek ip yok.", "{x} no es un espíritu errante: no hay hilo que cortar.", "{x} não é um espírito errante: não há fio para cortar.", "{x} — не блуждающий дух: нечего рассекать.", "{x} — не блукаючий дух: нічого розтинати."],
  "You shout from the belly. The {x} falters.": ["腹から叫ぶ。{x}がひるむ。", "배에서 외친다. {x}이(가) 움찔한다.", "你从丹田一喝。{x}一愣。", "你從丹田一喝。{x}一愣。", "Bạn hét từ bụng. {x} chùn lại.", "Kau berteriak dari perut. {x} goyah.", "คุณตะโกนจากท้อง {x}ชะงัก", "Karnından haykırırsın. {x} sendeler.", "Gritas desde el vientre. {x} vacila.", "Você grita da barriga. {x} vacila.", "Ты кричишь из живота. {x} сбивается.", "Ти кричиш із живота. {x} збивається."],
  "Lv {n}": ["Lv {n}", "Lv {n}", "等级 {n}", "等級 {n}", "Cấp {n}", "Lv {n}", "เลเวล {n}", "Sv {n}", "Nv {n}", "Nv {n}", "Ур. {n}", "Рів. {n}"],
